1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(org.springframework.samples.petclinic.util.PersonNameFormatter.displayName(owner.getFirstName(), owner.getLastName()))")
23	    @Mapping(target = "initials",
24	        expression = "java(org.springframework.samples.petclinic.util.PersonNameFormatter.initials(owner.getFirstName(), owner.getLastName()))")
25	    OwnerDto toOwnerDto(Owner owner);
26	
27	    Owner toOwner(OwnerDto ownerDto);
28	
29	    @Mapping(target = "id", ignore = true)
30	    @Mapping(target = "pets", ignore = true)
31	    @Mapping(target = "telephone",
32	        expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toE164(ownerDto.getTelephone()).orElse(null))")
33	    @Mapping(target = "email",
34	        expression = "java(org.springframework.samples.petclinic.util.EmailNormalizer.normalize(ownerDto.getEmail()))")
35	    Owner toOwner(OwnerFieldsDto ownerDto);
36	
37	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
38	
39	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
40	
41	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
42	        OwnerPageDto ownerPageDto = new OwnerPageDto();
43	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
44	        ownerPageDto.setPage(ownerPage.getNumber());
45	        ownerPageDto.setSize(ownerPage.getSize());
46	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
47	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
48	        return ownerPageDto;
49	    }
50	}
