18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.service.DuplicateTelephoneException;
34	import org.springframework.security.access.AccessDeniedException;
35	import org.springframework.validation.BindingResult;
36	import org.springframework.validation.FieldError;
37	import org.springframework.web.bind.MethodArgumentNotValidException;
38	import org.springframework.web.bind.annotation.ControllerAdvice;
39	import org.springframework.web.bind.annotation.ExceptionHandler;
40	import org.springframework.web.bind.annotation.ResponseBody;
41	
42	/**
43	 * Global Exception handler for REST controllers.
44	 * <p>
45	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
46	 *
47	 * @author Vitaliy Fedoriv
48	 * @author Alexander Dudkin
49	 */
50	@ControllerAdvice
51	public class ExceptionControllerAdvice {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
54	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
55	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
56	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
57	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone number already exists";
58	
59	    /**
60	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
61	     * class.
62	     *
63	     * @param e     Object referring to the thrown exception.
64	     * @param status HTTP response status.
65	     * @param url URL request.
66	     */
67	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
68	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
69	        problemDetail.setType(URI.create(url.toString()));
70	        problemDetail.setTitle(e.getClass().getSimpleName());
71	        problemDetail.setDetail(detail);
72	        problemDetail.setProperty("timestamp", Instant.now());
73	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
74	        return problemDetail;
75	    }
76	
77	    /**
78	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
79	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
80	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DuplicateTelephoneException} raised when creating an owner whose normalized telephone
109	     * number is already used by another owner, returning a 409 Conflict status.
110	     *
111	     * @param e The {@link DuplicateTelephoneException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
114	     */
115	    @ExceptionHandler(DuplicateTelephoneException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
118	        logger.warn("Duplicate telephone at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        HttpStatus status = HttpStatus.CONFLICT;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
124	        return ResponseEntity.status(status).body(detail);
125	    }
126	
127	    /**
128	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
129	     * method returns a 404 Not Found status if an entity does not exist.
130	     *
131	     * @param e The {@link DataIntegrityViolationException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
134	     */
135	    @ExceptionHandler(DataIntegrityViolationException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
138	        logger.warn("Data integrity violation at {} {}: {}",
139	            request.getMethod(),
140	            request.getRequestURI(),
141	            e.getMessage());
142	        logger.debug("Data integrity violation stacktrace", e);
143	        HttpStatus status = HttpStatus.NOT_FOUND;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
145	        return ResponseEntity.status(status).body(detail);
146	    }
147	
148	    /**
149	     * Handles exception thrown by Bean Validation on controller methods parameters
150	     *
151	     * @param e The {@link MethodArgumentNotValidException} to be handled
152	     * @param request {@link HttpServletRequest} object referring to the current request.
153	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
154	     */
155	    @ExceptionHandler(MethodArgumentNotValidException.class)
156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
158	        HttpStatus status = HttpStatus.BAD_REQUEST;
159	        BindingErrorsResponse errors = new BindingErrorsResponse();
160	        BindingResult bindingResult = e.getBindingResult();
161	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
162	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
163	            .map(FieldError::getField)
164	            .distinct()
165	            .toList());
166	        if (bindingResult.hasErrors()) {
167	            errors.addAllErrors(bindingResult);
168	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
169	                .map(fieldError -> {
170	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
171	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
172	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
173	                        fieldError.getField(),
174	                        defaultMessage,
175	                        rejectedValue);
176	                    return new ValidationMessageDto(message)
177	                        .putAdditionalProperty("field", fieldError.getField())
178	                        .putAdditionalProperty("rejectedValue", rejectedValue)
179	                        .putAdditionalProperty("defaultMessage", defaultMessage);
180	                })
181	                .toList();
182	            logger.debug("Validation error at {} {}: {}",
183	                request.getMethod(),
184	                request.getRequestURI(),
185	                bindingResult.getFieldErrors());
186	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
187	            return ResponseEntity.status(status).body(detail);
188	        }
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	}
