16	package org.springframework.samples.petclinic.repository.jdbc;
17	import org.springframework.boot.sql.init.dependency.DependsOnDatabaseInitialization;
18	import org.springframework.context.annotation.Profile;
19	import org.springframework.dao.DataAccessException;
20	import org.springframework.dao.EmptyResultDataAccessException;
21	import org.springframework.data.domain.Page;
